SELECT *
FROM approval_application
WHERE tenant_id = #{tenantId}
  AND applicant_user_id = #{applicantUserId}
  AND agent_operation_key = #{operationKey}
LIMIT 1

SELECT ,
       ,

FROM approval_application a

WHERE a.tenant_id = #{tenantId}
  AND a.id = #{id}

SELECT ,
       ,

FROM approval_application a

WHERE a.tenant_id = #{tenantId}
  AND a.applicant_user_id = #{applicantUserId}
  AND a.id = #{id}

SELECT ,
       NULL::text AS formSchemaSnapshot,
       NULL::integer AS formVersionSnapshot,
       NULL::text AS processNodeSnapshot,
       NULL::integer AS processVersionSnapshot,
       NULL::text AS ruleSnapshot,

FROM approval_application a

WHERE a.tenant_id = #{tenantId}
  AND a.applicant_user_id = #{userId}

    AND a.status = #{status}


    AND a.form_key = #{formKey}

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM approval_application
WHERE tenant_id = #{tenantId}
  AND applicant_user_id = #{userId}

    AND status = #{status}


    AND form_key = #{formKey}
